insert into public.cpl_memory (slug,kind,title,summary,tags,status,source,verified_by,verified_at,author,event_date) values
('sam-slash-joining-words-is-and-2026-11-18','decision','A slash joining words in a canonical credential title is written "and" (Sam, 2026-11-18)','Sam, in session S679, 2026-11-18: "I believe I replaced the / with and to avoid formatting issues and should be a general rule for other titles. UA Plumbers and Pipefitters". A slash joining words in a canonical title becomes "and"; a code slash and an official name''s slash stay (kb/slash_titles.py). Applied as rename plan slash-to-and-2026-11-18 (80 renames, run 44227947795).',array['cer-procedures','credential-naming','exhibits','sam'],'verified','Sam in session S679, 2026-11-18; docs/reference/sam_rulings.md; the line between word, code and official-name slashes drawn by the S679 conductor for Sam to revise','Sam Lee',now(),'SkyKinglet (S679)',date '2026-11-18'),
('d-short-high-scope-follows-catalog-range-s679','decision','Ruling 2 (short_high) is keyed on the catalog''s printed range, not on our sum''s shape','S679: Sam''s Nov 17 ruling 2 passes a record whose sum meets the low end of the catalog''s printed unit range and falls short of its high end; the sum may be a single figure. The conductor first narrowed it to range sums; COBIx''s count on #3478 corrected it. 165 records at 56 colleges (98 single-figure, 67 range), applied by run 44224714543.',array['program-requirements-harvest','rulings','scorer'],'proposed','#3478, #3481; kb/receipts/program_requirement_records_rescore_2026-11-18_s679.json','SkyKinglet (S679), the conductor',null,'SkyKinglet (S679)',date '2026-11-18'),
('d-slash-rule-line-s679','decision','Where the slash-to-and rule''s line falls: words take and, codes and official names stay','S679 conductor, on Sam''s slash ruling: (a) a slash joining words takes "and"; (b) a code slash stays (SP/2, CAD/CAM); (c) an official name''s slash stays (ASE test pairs, Fire Apparatus Driver/Operator, Medical/Surgical); C-ID descriptor titles are exempt; a spaced slash between two whole names is held for a person (7 held). kb/slash_titles.py; Sam may revise.',array['cer-procedures','credential-naming','exhibits'],'proposed','#3479; kb/cred_rename_plans/2026-11-18_slash_to_and.json','SkyKinglet (S679), the conductor',null,'SkyKinglet (S679)',date '2026-11-18'),
('d-left-map-move-only-unused-s679','decision','A title that left MAP takes Move or Remove only when nothing uses it','S679 conductor (#3477): Move changes only kb/unified_titles.json, and articulation rows carrying a used title stay grouped under the old canonical title in the reference bake, so a moved used title would sit in two places. The List offers Move only on titles kb/exhibit_left_map.json marks unused; a used title takes Keep, Rename or Combine; the apply holds a saved Move on a used title.',array['cer-procedures','exhibits','left-map'],'proposed','#3477; docs/reference/lanes/cer-procedures.md','SkyKinglet (S679), the conductor',null,'SkyKinglet (S679)',date '2026-11-18'),
('d-untyped-titles-two-press-s679','decision','An untyped title takes the combine guard''s two-press check, never a silent pass','S679 conductor (#3482, in progress): 1,025 of 2,849 canonical titles carry no CPL type, so the graded and cert-based combine guard cannot tell whether a fold crosses Sam''s groups. Such a fold gets an unknown two-press check: blocked on the first press, written on the second with the override logged.',array['cer-procedures','exhibits','combine-guard'],'proposed','#3482 (draft); docs/reference/lanes/cer-procedures.md','SkyKinglet (S679), the conductor',null,'SkyKinglet (S679)',date '2026-11-18'),
('d-course-list-note-is-the-mark-s679','decision','No confidence field exists for a course list, so a note is the only mark','S679 conductor (#3478): no filed program_requirement_records row carries a confidence field for its course list, so applying Sam''s Nov 17 rulings lowered nothing. 73 local degrees short of 60 carry "major matches; degree total short of 60, electives probably not listed", and 9 short required lists keep the lists_short note.',array['program-requirements-harvest','rulings','scorer'],'proposed','#3478','SkyKinglet (S679), the conductor',null,'SkyKinglet (S679)',date '2026-11-18'),
('d-ace-checks-warn-never-block-s679','decision','A failed ACE text check never blocks the MAP load','S679 conductor (#3468): a failed check on ACE''s CreditRecommendation text raises AceCheckFailed in kb/_sync_map_custom_reports.py; that night map_ace_catalog_cr is left alone, the MAP load goes ahead, and the run exits 1 at the end so the failure shows. Migration applied by run 44209026812; the first fill is the next 04:57 UTC load.',array['common-cr-reference','map-custom-reports','ace'],'proposed','#3468; kb/migrations/2026-11-17_s678_map_ace_catalog_cr.sql','SkyKinglet (S679), the conductor',null,'SkyKinglet (S679)',date '2026-11-18'),
('d-combine-guard-one-choke-point-s679','decision','The combine guard is one choke point that fails closed (the third-round redesign)','S679 conductor (#3477): after three review rounds of guard bypasses, every fold goes through foldWrite (one fold) or foldGate (a save that folds many), both reading foldLanding along listChainPath. It holds the fold while the CPL types file is unread, arms the second press per surface and pair, and logs each override as a cpl_type_group_override row.',array['cer-procedures','exhibits','combine-guard'],'proposed','#3477; docs/kb-notes/methodology-a-guard-must-fail-closed-when-it-cannot-decide.md','SkyKinglet (S679), the conductor',null,'SkyKinglet (S679)',date '2026-11-18'),
('p-dependency-map-serializes-merges-s679','pitfall','kb/dependency_map.json conflicts on every open PR after each merge','S679: each merge to main changed kb/dependency_map.json, so every other open PR conflicted; a PR in conflict gets no pull_request CI, and test takes about 11 minutes, so nine merges ran one at a time. Merge main, regenerate with python3 kb/_build_dependency_map.py, push, wait for test on the new head.',array['branch-policy','ci','dependency-map'],'proposed','docs/engineering_practices_lessons.md, 2026-11-18 S679','SkyKinglet (S679), the conductor',null,'SkyKinglet (S679)',date '2026-11-18'),
('p-apply-trigger-conflict-markers-s679','pitfall','A merge committed conflict markers into kb/migrations/.apply','S679: a merge of main ran git add -A over a conflicted kb/migrations/.apply and committed the markers; the migrate runner found no valid file= line and skipped, so nothing ran. Rule for workers: auto-resolve only kb/dependency_map.*, and stop and report on a conflict in any other file.',array['supabase-migrate','branch-policy','rule-10'],'proposed','docs/engineering_practices_lessons.md, 2026-11-18 S679','SkyKinglet (S679), the conductor',null,'SkyKinglet (S679)',date '2026-11-18'),
('m-slash-to-and-renames-applied-s679','milestone','The slash-to-and rename plan is applied: 80 canonical titles','S679, 2026-11-18 03:09Z: cred-rename-apply.yml run 44227947795 (only_plan=slash-to-and-2026-11-18) renamed 80 credential keys, 95 local-title values and 103 articulations; kb_curation 81 ok, 0 failed, 22 no-op; commit 64f13edc. Undo: kb/_cred_rename_undo.py kb/cred_rename_out/2026-11-18 (--supabase-plan for the kb_curation reversal).',array['cer-procedures','credential-naming','exhibits'],'proposed','kb/cred_rename_out/2026-11-18/validation.md','SkyKinglet (S679), the conductor',null,'SkyKinglet (S679)',date '2026-11-18'),
('m-prreq-rescore-applied-s679','milestone','Sam''s Nov 17 harvest rulings applied to 243 filed records','S679, 2026-11-18 02:41Z: supabase-migrate run 44224714543 applied the guarded UPDATE after a clean pre-read (run 44224061547): 243 program_requirement_records moved to arithmetic equal (165 short_high, 78 local-degree overlap); follow_verdict marked none checked. Rollback committed, not applied: kb/migrations/2026-11-18_s679_prreq_rescore_rollback.sql.',array['program-requirements-harvest','rulings','rule-10'],'proposed','#3481; kb/receipts/program_requirement_records_rescore_2026-11-18_s679.json','SkyKinglet (S679), the conductor',null,'SkyKinglet (S679)',date '2026-11-18'),
('pr-harness-worktree-cleanup-s679','procedure','Clean up a harness worktree: check the head, unlock, then remove','S679: a worker worktree inside the repo folder trips the stop hook, and harness worktrees stay locked after their agent finishes. Put worker worktrees outside the repo; to clean one, confirm its HEAD matches the pushed branch head, then git worktree unlock, then git worktree remove.',array['workers','worktrees','stop-hook'],'proposed','docs/engineering_practices_lessons.md, 2026-11-18 S679','SkyKinglet (S679), the conductor',null,'SkyKinglet (S679)',date '2026-11-18')
insert into public.cpl_memory_log (memory_id, actor, action, note, after)
